3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns the owner's {@code customerCode} as {@code <REGION>-<HASH8>}: the region code
12	 * derived from the postcode (see {@link Locality}), a hyphen, then the first eight
13	 * upper-case hex characters of the SHA-256 of the normalised telephone concatenated with
14	 * the last name. No sequence numbers are used, so the code is a stable function of the
15	 * owner's identity. Everything else built from the code — the membership number and its
16	 * check digit, the create audit line and the locality — follows from this same identity.
17	 */
18	public class AssignOwnerCustomerCode {
19	
20	    public void service(@Val Owner owner) {
21	        owner.setCustomerCode(Locality.of(owner) + "-" + hash8(owner.getTelephone() + owner.getLastName()));
22	    }
23	
24	    private static String hash8(String seed) {
25	        try {
26	            byte[] digest = MessageDigest.getInstance("SHA-256")
27	                    .digest(seed.getBytes(StandardCharsets.UTF_8));
28	            StringBuilder sb = new StringBuilder(8);
29	            for (int i = 0; i < 4; i++) {
30	                sb.append(String.format("%02X", digest[i]));
31	            }
32	            return sb.toString();
33	        }
34	        catch (NoSuchAlgorithmException e) {
35	            throw new IllegalStateException(e);
36	        }
37	    }
38	}
