11	 * Rejects a create once {@value #DAILY_LIMIT} or more owners already share the new
12	 * owner's (business-day adjusted) registration date.
13	 */
14	public class EnsureDailyOwnerLimitNotExceeded {
15	
16	    private static final int DAILY_LIMIT = 100;
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
19	            throws DailyOwnerLimitException {
20	        LocalDate registrationDate = owner.getRegistrationDate();
21	        long count = ownerRepository.findAll().stream()
22	                .filter(other -> registrationDate.equals(other.getRegistrationDate()))
23	                .count();
24	        if (count >= DAILY_LIMIT) {
25	            throw new DailyOwnerLimitException("The maximum number of owners for today has been reached");
26	        }
27	    }
28	}
