5	/**
6	 * Derives an owner's identity key — the single value all duplicate detection is based on.
7	 * It is the normalized telephone, the email (already lower-cased, empty when absent) and the
8	 * {@link HouseholdId}, joined by '|'. Two owners are duplicates only when their whole keys
9	 * match; a shared telephone, email or household alone is not enough.
10	 */
11	public final class IdentityKey {
12	
13	    private IdentityKey() {
14	    }
15	
16	    public static String of(Owner owner) {
17	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
18	        String email = owner.getEmail() == null ? "" : owner.getEmail();
19	        return telephone + "|" + email + "|" + HouseholdId.of(owner);
20	    }
