5	
6	/**
7	 * Decides the {@code bulkSignupWarning} flag: true once more than {@value #THRESHOLD}
8	 * other owners were already created on {@code owner}'s (business-day adjusted)
9	 * registration date, sharing the same accumulation path as the daily create limit.
10	 */
11	public final class BulkSignup {
12	
13	    private static final int THRESHOLD = 80;
14	
15	    private BulkSignup() {
16	    }
17	
18	    public static boolean isWarned(Owner owner, OwnerRepository ownerRepository) {
19	        long sameDay = ownerRepository.findAll().stream()
20	                .filter(other -> other.getId() != null && !other.getId().equals(owner.getId()))
21	                .filter(other -> owner.getRegistrationDate().equals(other.getRegistrationDate()))
22	                .count();
23	        return sameDay > THRESHOLD;
24	    }
25	}
